-- Kadikoy=Palo Alto, Besiktas=Sunnyvale, Ayse=Alex, Mehmet=Burak, Ali=Ferhat, Zeynep=Alejandro(admin)
update employee_profiles set archived_at=null where id='15000000-0000-4000-8000-000000fa0008';
update workspace_memberships set status='active', role='manager', role_id='bbbb6f06-0472-4230-984c-d58335df8b74' where workspace_id='6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1' and user_id='e8336f72-d18e-41bd-bb8d-fac7b8f74353';
update employee_location_assignments set ended_at=now() where employee_id='9abeff35-d9ad-4d55-bedd-dbf9a932e92b' and location_id='6b98d6ab-c5c3-433f-8b8c-1c6c1a8c437c' and ended_at is null;
update workspace_memberships set role='manager', role_id='bbbb6f06-0472-4230-984c-d58335df8b74' where workspace_id='6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1' and user_id='0021f57e-f379-4ae9-a099-689d7af46c62';
set constraints all immediate;
select 'scopes', u.first_name, string_agg(l.name, ',') from workspace_memberships m join employee_profiles u on u.user_id=m.user_id and u.workspace_id=m.workspace_id join membership_location_scopes s on s.membership_id=m.id join locations l on l.id=s.location_id where m.workspace_id='6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1' and m.role='manager' group by 2;
-- Besiktas published shift for Ali, Tue 2026-09-29 12:00-16:00
insert into schedule_location_publications(id,workspace_id,location_id,week_start,version_number,published_by) values('aaaaaaaa-0000-4000-8000-000000000001','6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1','bed21ebc-985f-432d-8f38-9d546cb3d13c','2026-09-28',1,'0021f57e-f379-4ae9-a099-689d7af46c62');
insert into schedule_published_shifts(workspace_id,location_id,publication_id,employee_id,job_id,scheduled_date,start_time,end_time,source_shift_id,time_basis) values('6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1','bed21ebc-985f-432d-8f38-9d546cb3d13c','aaaaaaaa-0000-4000-8000-000000000001','2768f70d-bd57-45b1-aecf-2dbce98bae8a','1a39b1fe-3213-438c-a4c5-5de3b6eacf60','2026-09-29','12:00','16:00',gen_random_uuid(),'explicit');
update workspace_scheduling_settings set minimum_travel_minutes=60 where workspace_id='6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1';
select 'T0 travel/rest', minimum_travel_minutes, minimum_rest_minutes from workspace_scheduling_settings where workspace_id='6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1';
select 'T1 acquire', r->>'status' from (select public.acquire_schedule_edit_session_service('e8336f72-d18e-41bd-bb8d-fac7b8f74353','6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1','2026-09-28','published') r) x;
select 'T2 mutate overlap create', left(public.mutate_schedule_edit_shift_service('e8336f72-d18e-41bd-bb8d-fac7b8f74353','6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1',s.id,s.revision,'create',null,null,jsonb_build_object('location_id','6b98d6ab-c5c3-433f-8b8c-1c6c1a8c437c','employee_id','2768f70d-bd57-45b1-aecf-2dbce98bae8a','job_id','1a39b1fe-3213-438c-a4c5-5de3b6eacf60','scheduled_date','2026-09-29','start_time','13:00','end_time','17:00','time_basis','explicit'),gen_random_uuid())::text,600) from schedule_edit_sessions s where s.workspace_id='6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1' and s.week_start='2026-09-28' and s.status='active';
select 'T3 assess travel 16:30-21:00 WITH session', jsonb_path_query_array(a,'$.reasons[*].code') from (select public.assess_schedule_shift_service('e8336f72-d18e-41bd-bb8d-fac7b8f74353','6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1',jsonb_build_object('location_id','6b98d6ab-c5c3-433f-8b8c-1c6c1a8c437c','employee_id','2768f70d-bd57-45b1-aecf-2dbce98bae8a','job_id','1a39b1fe-3213-438c-a4c5-5de3b6eacf60','scheduled_date','2026-09-29','start_time','16:30','end_time','21:00','time_basis','explicit'),null,(select id from schedule_edit_sessions where workspace_id='6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1' and week_start='2026-09-28' and status='active')) a) x;
select 'T4 assess travel 16:30-21:00 NO session', jsonb_path_query_array(a,'$.reasons[*].code') from (select public.assess_schedule_shift_service('e8336f72-d18e-41bd-bb8d-fac7b8f74353','6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1',jsonb_build_object('location_id','6b98d6ab-c5c3-433f-8b8c-1c6c1a8c437c','employee_id','2768f70d-bd57-45b1-aecf-2dbce98bae8a','job_id','1a39b1fe-3213-438c-a4c5-5de3b6eacf60','scheduled_date','2026-09-29','start_time','16:30','end_time','21:00','time_basis','explicit'),null,null) a) x;
select 'T5 save', left(public.save_schedule_edit_session_service('e8336f72-d18e-41bd-bb8d-fac7b8f74353','6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1',s.id,s.revision,'Kadikoy week',null,null,false)::text,300) from schedule_edit_sessions s where s.workspace_id='6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1' and s.week_start='2026-09-28' and s.status='active';
select 'T6 draft shifts', d.id, count(ds.*) from schedule_drafts d left join schedule_draft_shifts ds on ds.draft_id=d.id where d.workspace_id='6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1' and d.week_start='2026-09-28' group by d.id;
select 'T7 publish preview PA', left(public.preview_schedule_publication_service('e8336f72-d18e-41bd-bb8d-fac7b8f74353','6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1',(select id from schedule_drafts where workspace_id='6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1' and week_start='2026-09-28' and archived_at is null limit 1),array['6b98d6ab-c5c3-433f-8b8c-1c6c1a8c437c']::uuid[])::text,1500);
